/* FinanceFlow design system. All measurements are presentation-only. */
:root {
  color-scheme: dark;
  --bg: #101114;
  --surface: #18191e;
  --surface-raised: #202127;
  --surface-hover: #282930;
  --line: #303139;
  --line-soft: #26272e;
  --text: #f1f2f6;
  --muted: #acaebc;
  --subtle: #9497a8;
  --accent: #b5a4ff;
  --accent-fill: #c5b8ff;
  --accent-ink: #201735;
  --accent-surface: #29243b;
  --positive: #8ddbbc;
  --negative: #ffabb6;
  --warning: #ecc994;
  --space-1: 4px;
  --space-2: 8px;
  --space-3: 12px;
  --space-4: 16px;
  --space-5: 20px;
  --space-6: 24px;
  --space-8: 32px;
  --radius-sm: 9px;
  --radius: 14px;
  --radius-lg: 20px;
  --shadow: 0 12px 40px #0003;
  --nav-height: 66px;
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  font-size: 14px;
  line-height: 1.5;
  background: var(--bg);
  color: var(--text);
  -webkit-text-size-adjust: 100%;
}
* { box-sizing: border-box; }
body { margin: 0; background: var(--bg); }
button, input, select, textarea { font: inherit; }
button { cursor: pointer; -webkit-tap-highlight-color: transparent; }
a { color: var(--accent); }
button, input, select, textarea, summary { touch-action: manipulation; }
button:focus-visible, input:focus-visible, select:focus-visible, textarea:focus-visible, summary:focus-visible, a:focus-visible {
  outline: 2px solid var(--accent); outline-offset: 4px;
}
h1, h2, h3, p { margin: 0; }
h1 { font-size: clamp(26px, 3vw, 32px); line-height: 1.15; letter-spacing: -.8px; font-weight: 650; }
h2 { font-size: 16px; line-height: 1.4; font-weight: 620; letter-spacing: -.2px; margin-bottom: var(--space-4); }
h3 { font-size: 14px; font-weight: 600; margin-bottom: var(--space-2); }
strong { font-weight: 620; }
.icon-definitions { position: absolute; width: 0; height: 0; overflow: hidden; }
.icon { width: 21px; height: 21px; flex-shrink: 0; fill: none; stroke: currentColor; stroke-width: 1.7; stroke-linecap: round; stroke-linejoin: round; }
.hidden { display: none !important; }
.visually-hidden, .skip-link:not(:focus) { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }
.skip-link:focus { position: fixed; top: 8px; left: 8px; padding: 12px; background: var(--surface-raised); z-index: 100; }
.shell { max-width: 1440px; margin: auto; padding: max(16px, env(safe-area-inset-top)) max(16px, env(safe-area-inset-right)) calc(var(--nav-height) + 32px + env(safe-area-inset-bottom)) max(16px, env(safe-area-inset-left)); }
.top { display: flex; justify-content: space-between; align-items: center; gap: 12px; padding-bottom: 16px; border-bottom: 1px solid var(--line-soft); }
.brand { display: flex; align-items: center; gap: 10px; min-width: 0; }
.brand-mark { display: grid; place-items: center; width: 32px; height: 36px; color: var(--accent); }
.brand-mark .icon { width: 28px; height: 28px; stroke-width: 1.5; }
.logo { font-size: 18px; font-weight: 650; letter-spacing: -.6px; line-height: 1.3; }
.logo span { color: var(--text); }
.sync-status { font-size: 11px; letter-spacing: 0; color: var(--muted); font-weight: 400; margin-top: 3px; }
.cloud-tools { display: flex; align-items: center; gap: 6px; }
.cloud-tools .btn { width: 44px; padding: 0; background: transparent; border-color: transparent; }
.cloud-tools .btn span { display: none; }
.v2-status { color: var(--muted); font-size: 12px; padding: 12px 0 0; overflow-wrap: anywhere; }
.v2-status:empty { display: none; }
.v2-status.error { padding: 12px 14px; background: #322126; border: 1px solid #62404b; color: #ffbfca; border-radius: var(--radius-sm); margin-top: 12px; }
.hero { display: flex; justify-content: space-between; align-items: center; gap: 20px; margin: 24px 0 20px; flex-wrap: wrap; }
.hero > div:first-child { min-width: 0; }
.hero .muted { margin-top: 8px; max-width: 55ch; font-size: 13px; }
.eyebrow { color: var(--subtle); font-size: 10px; font-weight: 650; line-height: 1.5; letter-spacing: 1.4px; margin-bottom: 7px; }
.muted, .tiny, .metric-note, .foot, .txn-sub { color: var(--muted); }
.metric-note { font-size: 12px; line-height: 1.65; }
.tiny { font-size: 12px; line-height: 1.6; }
.foot { font-size: 12px; line-height: 1.7; margin-top: 16px; overflow-wrap: anywhere; }
.shell > .foot { color: var(--subtle); padding: 16px 0; font-size: 11px; }
.row, .section-title { display: flex; align-items: center; justify-content: space-between; gap: 12px; min-width: 0; }
.section-title { margin-bottom: 16px; flex-wrap: wrap; }
.section-title h2, .row > h2 { margin: 0; }
.section-title .metric-note { margin-top: 4px; }
.card { background: var(--surface); border: 1px solid var(--line-soft); border-radius: var(--radius); padding: 18px; min-width: 0; }
.section { margin-top: 16px; }
.grid, .summary-grid, .workgrid, .split, .dashboard-grid, .stats-grid { display: grid; gap: 12px; min-width: 0; }
.grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
#financeView > .grid > :first-child { grid-column: 1 / -1; background: var(--accent-surface); border-color: #49405e; }
#financeView > .grid > :first-child .metric { font-size: clamp(32px, 7vw, 42px); }
.summary-grid, .workgrid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
.split, .dashboard-grid, .stats-grid { grid-template-columns: minmax(0, 1fr); }
.dashboard-grid { margin-top: 16px; }
.metric { font-size: clamp(22px, 5.5vw, 30px); font-weight: 600; line-height: 1.2; letter-spacing: -.7px; margin: 12px 0 8px; overflow-wrap: anywhere; font-variant-numeric: tabular-nums; }
.metric-card { padding: 16px; }
.metric-card h2 { color: var(--muted); font-size: 12px; font-weight: 500; letter-spacing: 0; margin: 0; }
.positive { color: var(--positive); }
.negative { color: var(--negative); }
.overview-summary { display: grid; gap: 12px; }
.balance-summary { padding: 22px; border: 1px solid #49405e; border-radius: var(--radius-lg); background: var(--accent-surface); }
.balance-summary .eyebrow { color: #cec4e8; }
.balance-value { font-size: clamp(34px, 9vw, 48px); line-height: 1.2; letter-spacing: -1.6px; font-weight: 550; font-variant-numeric: tabular-nums; overflow-wrap: anywhere; margin: 14px 0 16px; }
.balance-context { display: flex; align-items: center; justify-content: space-between; gap: 12px; color: #cec8dd; font-size: 12px; }
.balance-currency { font-size: 10px; letter-spacing: 1px; padding: 4px 8px; border: 1px solid #5c5172; border-radius: 6px; }
.overview-metrics { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 0; border: 1px solid var(--line-soft); border-radius: var(--radius); background: var(--surface); }
.overview-metrics .card { border: 0; background: none; border-radius: 0; padding: 14px 10px; }
.overview-metrics .card + .card { border-left: 1px solid var(--line-soft); }
.overview-metrics h2 { font-size: 11px; }
.overview-metrics .metric { font-size: clamp(16px, 4.8vw, 25px); margin: 10px 0 6px; letter-spacing: -.5px; }
.overview-metrics .metric-note { font-size: 11px; line-height: 1.5; }
.quick-actions { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 8px; margin-top: 16px; }
.quick-actions .btn:first-child { background: var(--accent-fill); border-color: transparent; color: var(--accent-ink); }
.overview-foot { max-width: 90ch; }
.btn { display: inline-flex; justify-content: center; align-items: center; gap: 8px; min-height: 44px; padding: 11px 14px; border: 1px solid transparent; border-radius: var(--radius-sm); background: var(--accent-fill); color: var(--accent-ink); font-size: 13px; line-height: 1.35; font-weight: 600; text-align: center; text-decoration: none; transition: background-color .15s, border-color .15s; }
.btn.secondary { background: var(--surface-raised); border-color: var(--line); color: var(--text); }
.btn.danger { background: #3b242c; border-color: #5d3540; color: var(--negative); }
@media (hover: hover) { .btn:hover { background: #d4caff; } .btn.secondary:hover { background: var(--surface-hover); border-color: #545560; } }
button:disabled { opacity: .55; cursor: not-allowed; }
.toolbar { display: flex; align-items: flex-end; flex-wrap: wrap; gap: 10px; min-width: 0; }
.toolbar > * { min-width: 0; }
.toolbar input, .toolbar select { width: 100%; }
.toolbar .field { flex: 1 1 130px; }
.toolbar input[type=search] { flex: 1 1 180px; }
.date-tools { display: grid; grid-template-columns: 44px minmax(110px, 1fr) 44px auto; align-items: end; gap: 6px; width: 100%; }
.date-tools .btn { padding: 10px; }
.date-tools .field { font-size: 10px; }
.date-tools input { min-height: 44px; padding: 8px; font-size: 14px; }
.field { display: flex; flex-direction: column; gap: 7px; min-width: 0; font-size: 12px; color: #c8c9d2; line-height: 1.5; }
input, select, textarea { display: block; background: #111216; border: 1px solid #42434e; color: var(--text); border-radius: var(--radius-sm); padding: 11px 12px; width: 100%; min-width: 0; min-height: 46px; font-size: 16px; line-height: 1.4; }
input::placeholder, textarea::placeholder { color: var(--subtle); opacity: 1; }
textarea { resize: vertical; min-height: 94px; }
input[type=file] { font-size: 12px; padding: 12px; border-style: dashed; background: #141519; }
input[type=file]::file-selector-button { border: 0; border-radius: 6px; background: var(--surface-hover); color: var(--text); padding: 9px 12px; margin-right: 10px; font: inherit; }
input[type=search] { appearance: none; }
.month { width: 100%; }
.formgrid { display: grid; grid-template-columns: minmax(0, 1fr); gap: 16px; }
.full { grid-column: 1 / -1; }
.stack { display: flex; flex-direction: column; gap: 14px; }
.subnav { display: flex; flex-wrap: wrap; gap: 4px; padding: 4px; border: 1px solid var(--line-soft); border-radius: 12px; background: #131418; margin: 20px 0 16px; }
.subnav .btn { flex: 1; font-size: 12px; padding: 10px 8px; background: transparent; border: 0; color: var(--muted); }
.subnav .btn[aria-pressed=true] { background: var(--surface-hover); color: var(--text); }
.progress { height: 6px; background: #32333e; border-radius: 20px; overflow: hidden; margin-top: 12px; }
.progress > div { height: 100%; background: var(--accent); border-radius: inherit; }
.progress > div.over { background: var(--negative); }
.pill, .status-pill { display: inline-block; border-radius: 6px; padding: 4px 7px; font-size: 10px; line-height: 1.5; font-weight: 500; background: #25352f; color: #abdfc9; }
.status-pill.partial, .pill { color: #ccc5e2; background: #302c3d; }
.status-pill.uncertain { color: var(--warning); background: #3a3023; }
.notice, .note { padding: 12px 14px; border: 1px solid #5b4b33; border-radius: var(--radius-sm); background: #2c261d; color: #ebd0aa; font-size: 12px; line-height: 1.75; overflow-wrap: anywhere; }
.note { margin-top: 16px; background: #22212e; border-color: #444054; color: #c8c4d9; }
.notice p { margin-top: 8px; }
.empty { text-align: center; padding: 22px 14px; color: var(--muted); font-size: 13px; line-height: 1.7; max-width: 60ch; margin: auto; }
.empty-mark { display: grid; place-items: center; width: 32px; height: 32px; margin: 0 auto 10px; border: 1px solid var(--line); border-radius: 50%; color: var(--subtle); font-size: 20px; }
.empty p { margin: 0; }
.list-item { display: flex; justify-content: space-between; gap: 12px; padding: 18px 0; border-top: 1px solid var(--line-soft); flex-wrap: wrap; }
.list-item:first-child { border-top: 0; }
.list-main { flex: 1 1 200px; min-width: 0; }
.list-main > strong { display: block; font-size: 14px; line-height: 1.5; margin-bottom: 5px; overflow-wrap: anywhere; }
.list-main p { color: var(--muted); font-size: 12px; line-height: 1.7; margin: 5px 0; overflow-wrap: anywhere; }
.item-actions { display: flex; gap: 6px; align-items: flex-start; flex-wrap: wrap; }
.item-actions .btn { font-size: 12px; padding: 10px 13px; }
.entry-macros { display: flex; align-items: center; gap: 16px; margin: 10px 0 !important; }
.entry-macros strong { display: inline; font-size: 20px; color: var(--text); letter-spacing: -.3px; }
.entry-macros small { color: var(--muted); font-size: 12px; font-weight: 400; }
.diary-actions { width: 100%; justify-content: flex-start; }
.diary-actions .btn:last-child { margin-left: auto; color: var(--negative); }
details { min-width: 0; }
summary { cursor: pointer; min-height: 44px; padding: 11px 0; color: #d0c7ef; font-size: 12px; font-weight: 500; line-height: 1.6; }
details[open] > summary { margin-bottom: 14px; }
details p, details code { overflow-wrap: anywhere; }
.txn { display: grid; grid-template-columns: minmax(0, 1fr) auto 36px; align-items: center; gap: 8px; padding: 16px 0; border-top: 1px solid var(--line-soft); }
.txn:first-child { border-top: 0; }
.txn-main { min-width: 0; }
.txn-title { font-size: 13px; font-weight: 550; overflow-wrap: anywhere; }
.txn-sub { font-size: 11px; margin-top: 5px; }
.txn-amount { font-size: 14px; font-weight: 600; text-align: right; font-variant-numeric: tabular-nums; overflow-wrap: anywhere; max-width: 13ch; }
.delete { border: 0; border-radius: 8px; background: transparent; color: var(--muted); font-size: 22px; padding: 8px; min-width: 44px; min-height: 44px; }
.delete:hover { background: #35252c; color: var(--negative); }
.barrow { display: grid; grid-template-columns: minmax(65px, .6fr) minmax(20px, 1fr) auto; align-items: center; gap: 12px; font-size: 12px; margin: 18px 0; }
.barrow .progress { margin: 0; }
.barrow strong { font-variant-numeric: tabular-nums; }
.cat { margin: 16px 0; }
hr { border: 0; border-top: 1px solid var(--line); margin: 20px 0; }
.compact-chart, .workgraph { width: 100%; height: auto; display: block; margin: 16px 0; overflow: visible; }
.compact-chart { min-height: 150px; }
.chart-grid, .workgraph .axis { stroke: #33343e; stroke-width: 1; }
.chart-label, .workgraph text { fill: #b5b6c4; font-size: 12px; }
.chart-bar, .workgraph .barwork { fill: #ad9de6; }
.chart-estimate { fill: #d3b27f; }
.chart-dot, .workgraph .barpay { fill: var(--positive); }
.chart-line { fill: none; stroke: var(--positive); stroke-width: 2; }
.legend, .graphlegend { display: flex; flex-wrap: wrap; gap: 12px 18px; font-size: 11px; color: var(--muted); }
.legend span::before, .graphlegend i { content: ''; display: inline-block; width: 7px; height: 7px; margin-right: 7px; border-radius: 2px; background: #ad9de6; }
.legend .estimate::before { background: #d3b27f; }
.weight-references { display: flex; gap: 20px; flex-wrap: wrap; }
.weight-references span { display: block; font-size: 12px; color: var(--muted); }
.weight-references strong { display: block; font-size: 23px; margin: 8px 0; font-variant-numeric: tabular-nums; }
.data-table, .worktable { width: 100%; border-collapse: collapse; font-size: 12px; }
.data-table th, .worktable th { color: var(--muted); font-weight: 500; text-align: left; white-space: nowrap; }
.data-table th, .data-table td, .worktable th, .worktable td { padding: 13px 10px; border-bottom: 1px solid var(--line-soft); text-align: left; overflow-wrap: anywhere; }
.table-scroll, .worktable-wrap { min-width: 0; }
#settingsView > .card { margin-top: 12px; }
#settingsView .backups-section .toolbar { margin-top: 16px; }
.preference-section > details > summary { color: var(--text); font-size: 15px; font-weight: 550; }
.import-section { margin-top: 24px !important; }
.import-section .field { margin-top: 16px; }
.import-section > .toolbar { margin-top: 16px; }
.import-steps { display: flex; flex-wrap: wrap; gap: 12px; list-style: none; padding: 16px 0; margin: 16px 0; border-block: 1px solid var(--line-soft); }
.import-steps li { display: flex; align-items: center; gap: 7px; font-size: 11px; color: var(--muted); }
.import-steps span { display: grid; place-items: center; width: 22px; height: 22px; border-radius: 50%; background: var(--surface-hover); color: #d0c9e5; font-size: 10px; }
.import-counts { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); margin: 24px 0 14px; padding: 16px 0; border-block: 1px solid var(--line); }
.import-counts > div { display: flex; flex-direction: column; gap: 4px; }
.import-counts > div + div { padding-left: 12px; border-left: 1px solid var(--line-soft); }
.import-counts strong { font-size: 26px; line-height: 1.2; font-variant-numeric: tabular-nums; }
.import-counts span { color: var(--muted); font-size: 11px; }
.import-records { list-style: none; padding: 0; margin: 0; display: grid; gap: 10px; }
.import-record { min-width: 0; border: 1px solid var(--line); background: #141519; border-radius: var(--radius-sm); padding: 14px; }
.import-record-heading { display: flex; align-items: center; justify-content: space-between; gap: 12px; margin-bottom: 12px; }
.import-record-heading .eyebrow { margin: 0; font-size: 9px; letter-spacing: 1px; }
.import-record h3 { font-size: 14px; font-weight: 550; overflow-wrap: anywhere; }
.import-record p, .import-record time { font-size: 12px; line-height: 1.65; color: var(--muted); overflow-wrap: anywhere; }
.import-record time { display: block; margin: 6px 0; }
.import-record details { margin-top: 4px; }
.import-record summary { min-height: 44px; padding: 12px 0 4px; font-size: 11px; }
.import-record code { display: block; font-size: 11px; color: var(--muted); }
.import-action { font-size: 11px; font-weight: 600; border-radius: 6px; padding: 4px 8px; white-space: nowrap; }
.import-action.create { color: #a5e3c9; background: #203a2f; }
.import-action.skip { color: #c6c7d4; background: #2c2e39; }
.import-action.flag { color: #f5d3a1; background: #403124; }
.tabs { position: fixed; bottom: 0; left: 0; right: 0; display: flex; justify-content: space-around; align-items: stretch; padding: 4px max(8px, env(safe-area-inset-right)) max(4px, env(safe-area-inset-bottom)) max(8px, env(safe-area-inset-left)); min-height: var(--nav-height); border-top: 1px solid var(--line); background: #16171cf7; z-index: 10; }
.tabs .btn { flex: 1; min-width: 0; min-height: 56px; display: flex; flex-direction: column; gap: 5px; padding: 7px 2px; background: transparent; border: 0; border-radius: 8px; color: var(--muted); font-size: 10px; font-weight: 500; }
.tabs .btn.active { color: #d6caff; background: #292538; }
.tabs [data-secondary] { display: none; }
.keyboard-open .tabs { display: none; }
dialog { color: var(--text); background: var(--surface); border: 1px solid #45434f; border-radius: var(--radius-lg); padding: 22px; width: min(620px, calc(100% - 24px)); max-height: calc(var(--viewport-height, 100dvh) - 32px); overflow: auto; overscroll-behavior: contain; box-shadow: var(--shadow); }
dialog::backdrop { background: #050609bf; }
dialog h2 { font-size: 21px; margin-bottom: 22px; }
.dialog-actions { display: flex; gap: 10px; justify-content: flex-end; padding-top: 16px; margin-top: 6px; border-top: 1px solid var(--line); }
.dialog-actions .btn { flex: 1; }
.auth-error { color: var(--negative); font-size: 13px; min-height: 18px; overflow-wrap: anywhere; }
.navigation-sheet { margin: auto auto 0; width: 100%; max-width: 560px; padding: 24px 20px calc(20px + env(safe-area-inset-bottom)); border-radius: 22px 22px 0 0; border-bottom: 0; }
.sheet-heading { display: flex; justify-content: space-between; align-items: flex-start; gap: 14px; margin-bottom: 20px; }
.sheet-heading h2 { font-size: 20px; margin: 0; }
.sheet-heading > .btn { width: 44px; padding: 0; font-size: 22px; }
.more-links { display: grid; gap: 8px; }
.more-links .btn { justify-content: flex-start; padding: 16px; text-align: left; gap: 16px; }
.more-links .btn > span:nth-child(2) { flex: 1; }
.more-links small { display: block; color: var(--muted); font-weight: 400; font-size: 12px; margin-top: 4px; }
.auth-overlay { position: fixed; inset: 0; background: #101114f5; z-index: 30; display: flex; align-items: center; justify-content: center; padding: 16px; overflow-y: auto; }
.auth-card { width: min(100%, 400px); background: var(--surface); border: 1px solid var(--line); border-radius: var(--radius-lg); padding: 28px; }
.auth-card h2 { font-size: 23px; margin-bottom: 10px; }
.auth-card p { font-size: 13px; line-height: 1.7; }
.auth-card form { display: grid; gap: 16px; margin-top: 24px; }
.toast { position: fixed; bottom: calc(var(--nav-height) + 16px + env(safe-area-inset-bottom)); left: 16px; right: 16px; width: fit-content; max-width: calc(100% - 32px); margin: auto; padding: 13px 18px; border: 1px solid #575264; border-radius: var(--radius-sm); background: #302b3d; color: var(--text); font-size: 13px; display: none; z-index: 20; box-shadow: var(--shadow); }
@media (min-width: 430px) {
  .formgrid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .shell { padding-inline: max(22px, env(safe-area-inset-left)) max(22px, env(safe-area-inset-right)); }
  .card { padding: 20px; }
}
@media (min-width: 768px) {
  .shell { padding: 24px 32px 60px 232px; }
  .top { padding-bottom: 20px; }
  .logo { font-size: 20px; }
  .cloud-tools .btn { width: auto; padding: 10px 14px; }
  .cloud-tools .btn span { display: inline; }
  .tabs { inset: 0 auto 0 0; width: 200px; padding: 120px 14px 24px; flex-direction: column; justify-content: flex-start; gap: 5px; border-top: 0; border-right: 1px solid var(--line-soft); background: #141519; }
  .tabs::before { content: 'WORKSPACE'; position: absolute; top: 82px; left: 26px; font-size: 10px; letter-spacing: 1.5px; color: var(--subtle); }
  .tabs .btn, .tabs [data-secondary] { display: flex; flex: 0 0 auto; flex-direction: row; gap: 12px; min-height: 46px; padding: 12px; font-size: 12px; justify-content: flex-start; text-align: left; }
  .tabs .btn .icon { width: 18px; height: 18px; }
  #moreNav { display: none; }
  .hero { margin: 28px 0 24px; }
  .date-tools { width: auto; min-width: 320px; }
  .date-tools .field { max-width: 180px; }
